import React, { useMemo, useState } from 'react';

function LogTable({
  logs,
  onSelectLog,
  onRowClick,

  onExport,         // (format, ids) => Promise<void>
  onExportAll,      // (format) => Promise<void>   ✅ 추가: 필터 기반 전체 내보내기
  onDeleteSelected, // (ids) => Promise<void>
  onDeleteOne,      // (id) => Promise<void>
}) {
  const rowClickHandler = onSelectLog || onRowClick;

  const [selectedIds, setSelectedIds] = useState(() => new Set());

  const selectedCount = selectedIds.size;

  const allChecked = useMemo(() => {
    if (!logs || logs.length === 0) return false;
    return logs.every((l) => selectedIds.has(l.id));
  }, [logs, selectedIds]);

  const someChecked = useMemo(() => {
    if (!logs || logs.length === 0) return false;
    const cnt = logs.filter((l) => selectedIds.has(l.id)).length;
    return cnt > 0 && cnt < logs.length;
  }, [logs, selectedIds]);

  const toggleAll = () => {
    if (!logs || logs.length === 0) return;

    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (logs.every((l) => next.has(l.id))) {
        logs.forEach((l) => next.delete(l.id));
      } else {
        logs.forEach((l) => next.add(l.id));
      }
      return next;
    });
  };

  const toggleOne = (id) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const clearSelection = () => setSelectedIds(new Set());

  const handleExportSelected = async (format) => {
    if (!onExport) return;
    const ids = Array.from(selectedIds);
    await onExport(format, ids);
  };

  const handleExportAll = async (format) => {
    if (!onExportAll) return;
    await onExportAll(format);
  };

  const handleDeleteSelected = async () => {
    if (!onDeleteSelected) return;
    const ids = Array.from(selectedIds);
    await onDeleteSelected(ids);
    clearSelection();
  };

  const handleDeleteOne = async (e, id) => {
    e.stopPropagation();
    if (!onDeleteOne) return;

    await onDeleteOne(id);
    setSelectedIds((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  };

  if (!logs || logs.length === 0) {
    return <p>표시할 로그가 없습니다.</p>;
  }

  return (
    <div className="log-table-wrapper">
      {/* 상단 툴바 */}
      <div
        className="log-table-toolbar"
        style={{
          display: 'flex',
          gap: 8,
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: 10,
          flexWrap: 'wrap',
        }}
      >
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <strong>선택: {selectedCount}개</strong>
          <button className="btn" onClick={clearSelection} disabled={selectedCount === 0}>
            선택 해제
          </button>
        </div>

        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
          {/* ✅ 선택 내보내기 */}
          <button
            className="btn"
            onClick={() => handleExportSelected('CSV')}
            disabled={selectedCount === 0}
            title="체크한 로그만 내보내기"
          >
            선택 CSV
          </button>
          <button
            className="btn"
            onClick={() => handleExportSelected('JSON')}
            disabled={selectedCount === 0}
            title="체크한 로그만 내보내기"
          >
            선택 JSON
          </button>

          {/* ✅ 필터 전체 내보내기 */}
          <button
            className="btn"
            onClick={() => handleExportAll('CSV')}
            disabled={!onExportAll}
            title="현재 필터 조건 전체를 내보내기(선택과 무관)"
          >
            전체 CSV
          </button>
          <button
            className="btn"
            onClick={() => handleExportAll('JSON')}
            disabled={!onExportAll}
            title="현재 필터 조건 전체를 내보내기(선택과 무관)"
          >
            전체 JSON
          </button>

          {/* 삭제 */}
          <button className="btn" onClick={handleDeleteSelected} disabled={selectedCount === 0}>
            선택 삭제
          </button>
        </div>
      </div>

      <table className="log-table">
        <thead>
          <tr>
            <th style={{ width: 40 }}>
              <input
                type="checkbox"
                checked={allChecked}
                ref={(el) => {
                  if (el) el.indeterminate = someChecked;
                }}
                onChange={toggleAll}
              />
            </th>
            <th>ID</th>
            <th>수집 시각</th>
            <th>이벤트</th>
            <th>경로</th>
            <th>크기</th>
            <th>위험도</th>
            <th style={{ width: 90 }}>삭제</th>
          </tr>
        </thead>

        <tbody>
          {logs.map((log) => (
            <tr
              key={log.id}
              onClick={() => rowClickHandler?.(log)}
              style={{ cursor: rowClickHandler ? 'pointer' : 'default' }}
            >
              <td onClick={(e) => e.stopPropagation()}>
                <input
                  type="checkbox"
                  checked={selectedIds.has(log.id)}
                  onChange={() => toggleOne(log.id)}
                />
              </td>
              <td>{log.id}</td>
              <td>{log.collectedAt || '-'}</td>
              <td>{log.eventType || '-'}</td>
              <td title={log.path}>{log.path || '-'}</td>
              <td>{log.size != null ? log.size : '-'}</td>
              <td>{log.aiLabel || '-'}</td>
              <td>
                <button
                  className="btn"
                  onClick={(e) => handleDeleteOne(e, log.id)}
                  disabled={!onDeleteOne}
                  title={!onDeleteOne ? '삭제 핸들러가 연결되지 않았습니다.' : '이 로그 삭제'}
                >
                  삭제
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default LogTable;
